import React, { Component, useState, useRef, useEffect } from "react";
import Header from "./Header";
import Footer from './Footer';
import axios from "axios";
import { withRouter } from "react-router-dom";
import Box from "@material-ui/core/Box";
import TextField from "@mui/material/TextField";
import "./Agree.css";
import "./Home.css";
import ViewArtifact_checkedFalse from "./ViewArtifact_checkedFalse";
import ViewArtifact_checkedTrue from "./ViewArtifact_checkedTrue";
import TypeChooser from "./TypeChooser";
import SearchIcon from "@mui/icons-material/Search";
import Typography from "@mui/material/Typography";
import Snackbar from "@mui/material/Snackbar";
import Button from "@mui/material/Button";
import Modal from "@mui/material/Modal";
import "./UploadEvidence_artifact.css";
import ReactTagInput from "@pathofdev/react-tag-input";
import "@pathofdev/react-tag-input/src/styles/index.css";
import MuiAlert from "@mui/material/Alert";
import Switch from "@mui/material/Switch";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogContent from "@mui/material/DialogContent";
import DialogContentText from "@mui/material/DialogContentText";
import DialogTitle from "@mui/material/DialogTitle";
import Stack from "@mui/material/Stack";

const modal_style = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  width: "35%",
  height: "40%",
  bgcolor: "background.paper",
  textAlign: "center",
  boxShadow: 10,
  borderRadius: "8px",
  p: 4,
};

const Alert = React.forwardRef(function Alert(props, ref) {
  return <MuiAlert elevation={6} ref={ref} variant="filled" {...props} />;
});

let keyword = "";

class UploadEvidence_artifact extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isHolidayOpen: false,
      isParentalOpen: false,
      fileVerify: false,
      isSnackbarOpen: false,
      isDetail: false,
      user: "",
      file: null,
      fileName: "",
      isListOpen: false,
      originalArtifact: [],
      artifactList: [],
      attacker: [],
      description: "",
      id: "",
      value: "1",
      type: "",
      keyword: "",
      keyword_input: "",
      startTime: "0000-00-00T00:00",
      endTime: "9999-99-99T99:99",
      startTime_input: "0000-00-00T00:00",
      endTime_input: "9999-99-99T99:99",
      isModalOpen: false,
      work_startTime: "00:00",
      work_endTime: "99:99",
      work_startTime_input: "00:00",
      work_endTime_input: "99:99",
      holiday_date: "",
      parental_date: "",
    };
    this.loadData = this.loadData.bind(this);
    this.handleFormSubmit = this.handleFormSubmit.bind(this);
    this.handleValueChange = this.handleValueChange.bind(this);
    this.handleFileChange = this.handleFileChange.bind(this);
    this.addEvidence = this.addEvidence.bind(this);
    this.getData = this.getData.bind(this);
    this.submitButton = this.submitButton.bind(this);
    this.setAttacker = this.setAttacker.bind(this);
    this.setDescription = this.setDescription.bind(this);
    this.getType = this.getType.bind(this);
    this.UserChooserOpen = this.UserChooserOpen.bind(this);
    this.checkedListOpen = this.checkedListOpen.bind(this);
    this.go = this.go.bind(this);
    // this.typographyOpen = this.typographyOpen.bind(this);
    this.modalOpen = this.modalOpen.bind(this);
    this.modalClose = this.modalClose.bind(this);
    this.snackbarOpen = this.snackbarOpen.bind(this);
    this.snackbarClose = this.snackbarClose.bind(this);
  }

  componentDidMount() {
    this.timer = setInterval(this.progress, 20);
    this.intervalId = setInterval(() => this.loadData(), 3000);
    this.loadData();
  }
  componentWillUnmount() {
    clearInterval(this.intervalId);
  }

  go() {
    this.props.history.goBack();
  }

  async callApi() {
    let body = {
      user: this.props.location.state.user,
      casenum: "0",
    };
    if (keyword) {
      let res = axios.get(
        "/getevidences?keyword=" +
          keyword +
          "&casenum=" +
          this.props.location.state.casenum
      );

      return res;
    } else {
      return axios.post("/getevidences", body);
    }
  }

  async loadData() {
    const res = await axios.get("/getuser");
    this.state.user = res.data.user;

    this.callApi()
      .then((res) => {
        this.setState({ boards: res.data });
      })
      .catch((err) => console.log(err));
  }

  handleFormSubmit(e) {
    e.preventDefault();
    this.callUserApi().catch((err) => console.log(err));
  }

  handleValueChange(e) {
    let nextState = {};
    nextState[e.target.name] = e.target.value;
    this.setState(nextState);
  }

  handleFileChange(e) {
    console.log(e.target.files[0].name);
    this.setState({
      file: e.target.files[0],
      fileName: e.target.files[0].name,
    });
  }

  addEvidence() {
    const formData = new FormData();
    formData.append("file", this.state.file);
    formData.append("filename", this.state.fileName);
    formData.append("user", this.state.user);
    formData.append("case_num", this.props.location.state.casenum);
    const config = {
      headers: {
        enctype: "multipart/form-data",
      },
    };
    axios.post("/loadArtifactFile", formData, config).then((res) => {
      if (res.data.res == "verified fail") {
        alert(
          "임의로 편집된 파일은 업로드가 불가능합니다. 원본 파일을 업로드 해 주세요."
        );
      } else {
        this.setState({ fileVerify: true });
      }
      // console.log(res.data.data);

      this.setState({ artifactList: res.data.data });
      this.setState({ originalArtifact: res.data.data });
      // this.setState({ artifactList: res.data.data });
      // this.setState({ id: res.data._id.$oid });
    });
  }

  async callUserApi() {
    try {
      const res = await axios.get("/getuser");
      this.state.user = res.data.user;

      this.addEvidence();
    } catch (err) {
      return console.log(err);
    }
  }

  handleSwitchClick = (event) => {
    console.log(event.target.checked);
    this.setState({ isDetail: event.target.checked });
  };

  snackbarOpen() {
    this.setState({ isSnackbarOpen: true });
  }

  snackbarClose = (event, reason) => {
    if (reason === "clickaway") {
      return;
    }
    this.setState({ isSnackbarOpen: false });
  };

  parentalOpen = () => {
    this.setState({ isParentalOpen: true });
  };

  parentalClose = () => {
    this.setState({ isParentalOpen: false });
  };

  holidayOpen = () => {
    this.setState({ isHolidayOpen: true });
  };

  holidayClose = () => {
    this.setState({ isHolidayOpen: false });
  };

  modalOpen() {
    this.setState({ isModalOpen: true });
  }

  modalClose() {
    this.setState({ isModalOpen: false });
  }

  getHolidayDate = (e) => {
    console.log(e.target.value);
    this.setState({ holiday_date: e.target.value });
  };

  getParentalDate = (e) => {
    this.setState({ parental_date: e.target.value });
  };

  getworkStartTime = (event) => {
    if (event.target.value) {
      this.setState({ work_startTime: event.target.value });
      console.log(event.target.value);
    } else {
      this.setState({ work_endTime: "00:00" });
    }
  };

  getworkEndTime = (event) => {
    if (event.target.value) {
      this.setState({ work_endTime: event.target.value });
      console.log(event.target.value);
    } else {
      this.setState({ work_endTime: "00:00" });
    }
  };

  getStartTime = (event) => {
    console.log(event.target.value);
    if (event.target.value) {
      this.setState({ startTime: event.target.value });
    } else {
      this.setState({ startTime: "0000-00-00T00:00" });
    }
  };

  getEndTime = (event) => {
    console.log(event.target.value);
    if (event.target.value) {
      this.setState({ endTime: event.target.value });
    } else {
      this.setState({ endTime: "9999-99-99T99:99" });
    }
  };

  getData(data) {
    this.setState({ artifactList: data });
    // console.log(data);
  }

  getType(type) {
    console.log(type);
    this.setState({ type: type });
    if (type === "초과근무"||type==="SNS") {
      this.setState({ isModalOpen: true });
    } else if (type === "휴가") {
      this.holidayOpen();
    } else if (type === "육아휴직") {
      this.setState({ isParentalOpen: true });
    }
  }
  UserChooserOpen() {
    if (this.state.isListOpen && this.state.fileVerify) {
      return (
        <div className="jb-upload-com-flex-column-container">
          
          
          <TypeChooser getType={this.getType} />
          

          <TextField
            className="jb-upload-select-date"
            id="datetime-local"
            label="start time"
            type="datetime-local"
            defaultValue=""
            // sx={{ width: 250 }}
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(event) => this.getStartTime(event)}
          />
          
          <div style={{ marginLeft: "0.5%", marginRight: "0.5%" }}>
            <Typography variant="h5" style={{ color: "#4B64D4" }}>
              ~
            </Typography>
          </div>
          
          <TextField
            className="jb-upload-select-date"
            id="datetime-local"
            label="end time"
            type="datetime-local"
            // sx={{ width: 250 }}
            InputLabelProps={{
              shrink: true,
            }}
            onChange={(event) => this.getEndTime(event)}
          />

          <div className="jb-upload-search-box">
            <input
              className="search-text-box"
              type="search"
              placeholder="    검색어를 입력하세요"
              onChange={this.setKeyword}
              />
            <button className="search_button"  onClick={() => {this.setState({
                startTime_input: this.state.startTime,
                endTime_input: this.state.endTime,
                keyword_input: this.state.keyword,
              });
            }}/>
          </div>

          {/* <div
            className="jb-upload-search-box"
            // fullWidth
            id="filled-search"
            label="검색"
            type="search"
            // variant="filled"
            onChange={this.setKeyword}
            // size="large"
          >
            <Button
            onClick={() => {
              this.setState({
                startTime_input: this.state.startTime,
                endTime_input: this.state.endTime,
                keyword_input: this.state.keyword,
              });
            }}
          >
            <SearchIcon color="primary" fontSize="large"></SearchIcon>
          </Button>
        </div> */}
          
        <span className="jb-upload-see-all-text">
          전체 보기
        </span>
        <Switch
          checked={this.state.isDetail}
          onChange={this.handleSwitchClick}
        />
          <br></br>
        </div>
      );
    }
  }

  // typographyOpen() {
  //   if (this.state.isListOpen && this.state.fileVerify) {
  //     return (

  //     );
  //   }
  // }

  listOpen() {
    if (this.state.isListOpen && this.state.fileVerify) {
      return (
        <div>
          <div style={{ transition: "all.5s ease" }}>
            <Dialog
              open={this.state.isHolidayOpen}
              onClose={() => this.holidayClose()}
            >
              <DialogTitle>휴가</DialogTitle>
              <DialogContent>
                <DialogContentText>
                  휴가 날짜를 선택하세요<div style={{ width: "400px" }}></div>
                </DialogContentText>
                <TextField
                  autoFocus
                  margin="dense"
                  type="date"
                  fullWidth
                  variant="standard"
                  onChange={(e) => this.getHolidayDate(e)}
                />
              </DialogContent>
              <DialogActions style={{ textAlign: "center" }}>
                <Button
                  style={{ color: "#4B64D4" }}
                  onClick={() => this.holidayClose()}
                >
                  취소
                </Button>
                <Button
                  style={{ color: "#4B64D4" }}
                  onClick={() => this.holidayClose()}
                >
                  확인
                </Button>
              </DialogActions>
            </Dialog>

            <Dialog
              open={this.state.isParentalOpen}
              onClose={() => this.parentalClose()}
            >
              <DialogTitle>육아휴직</DialogTitle>
              <DialogContent>
                <DialogContentText>
                  육아 휴직 날짜를 선택하세요
                  <div style={{ width: "400px" }}></div>
                </DialogContentText>
                <TextField
                  autoFocus
                  margin="dense"
                  type="date"
                  fullWidth
                  variant="standard"
                  onChange={(e) => this.getParentalDate(e)}
                />
              </DialogContent>
              <DialogActions style={{ textAlign: "center" }}>
                <Button
                  style={{ color: "#4B64D4" }}
                  onClick={() => this.parentalClose()}
                >
                  취소
                </Button>
                <Button
                  style={{ color: "#4B64D4" }}
                  onClick={() => this.parentalClose()}
                >
                  확인
                </Button>
              </DialogActions>
            </Dialog>

            <Modal
              style={{ transition: "all.5s ease" }}
              open={this.state.isModalOpen}
              onClose={this.modalClose}
            >
              <div>
                <Box sx={modal_style}>
                  <Typography
                    style={{
                      color: "#4B64D4",
                      fontFamily: "NanumSquare-Regular",
                      fontWeight: "bold",
                    }}
                    variant="h4"
                  >
                    근무 시간 선택
                  </Typography>
                  <Typography
                    variant="h5"
                    sx={{ mt: 2 }}
                    style={{ fontFamily: "NotoSansKR-Light", color: "#3F3F3F" }}
                  >
                    정규 근무 시간을 선택해주세요
                  </Typography>

                  <br></br>
                  <div style={{ display: "flex", justifyContent: "center" }}>
                    <div style={{ marginRight: "9%" }}>
                      <Typography
                        style={{
                          color: "#4B64D4",
                          fontFamily: "NanumSquare-Regular",
                          fontWeight: "bold",
                        }}
                        variant="h6"
                      >
                        시작시간
                      </Typography>
                    </div>
                    <div style={{ marginLeft: "9%" }}>
                      <Typography
                        style={{
                          color: "#4B64D4",
                          fontFamily: "NanumSquare-Regular",
                          fontWeight: "bold",
                        }}
                        variant="h6"
                      >
                        종료시간
                      </Typography>
                    </div>
                  </div>
                  <div style={{ lineHeight: "65%" }}>
                    <br></br>
                  </div>
                  <div style={{ display: "flex", justifyContent: "center" }}>
                    <div style={{ marginRight: "8%" }}>
                      <TextField
                        type="time"
                        defaultValue="00:00"
                        InputLabelProps={{
                          shrink: true,
                        }}
                        onChange={(event) => this.getworkStartTime(event)}
                      />
                    </div>
                    <div>
                      <TextField
                        type="time"
                        defaultValue="00:00"
                        InputLabelProps={{
                          shrink: true,
                        }}
                        onChange={(event) => this.getworkEndTime(event)}
                      />
                    </div>
                  </div>
                  <div style={{ lineHeight: "65%" }}>
                    <br></br>
                  </div>
                  <br></br>
                  <div style={{ textAlign: "center" }}>
                    <Button
                      variant="contained"
                      style={{ marginRight: "5%" }}
                      onClick={() => {
                        this.modalClose();
                        this.setState({
                          work_startTime_input: this.state.work_startTime,
                          work_endTime_input: this.state.work_endTime,
                        });
                      }}
                    >
                      <Typography variant="h7">확인</Typography>
                    </Button>
                    <Button
                      onClick={() => {
                        this.modalClose();
                        this.setState({
                          work_startTime_input: "00:00",
                          work_endTime_input: "99:99",
                        });
                      }}
                    >
                      <Typography variant="h7">취소</Typography>
                    </Button>
                  </div>
                </Box>
              </div>
            </Modal>
          </div>

          <div>
            <ViewArtifact_checkedFalse
              startTime={this.state.startTime_input}
              endTime={this.state.endTime_input}
              data={this.state.artifactList}
              id={this.state.id}
              getData={this.getData}
              type={this.state.type}
              keyword={this.state.keyword_input}
              work_startTime={this.state.work_startTime_input}
              work_endTime={this.state.work_endTime_input}
              isDetail={this.state.isDetail}
            />
          </div>
        </div>
      );
    }
  }
  checkedListOpen() {
    if (this.state.isListOpen && this.state.fileVerify) {
      return (
        <div>
          <ViewArtifact_checkedTrue
            data={this.state.artifactList}
            id={this.state.id}
            getData={this.getData}
            type={this.state.type}
          />
        </div>
      );
    }
  }

  userInputOpen() {
    if (this.state.isListOpen && this.state.fileVerify) {
      return (
        <>
          <br></br>
          <Box
            component="form"
            sx={{
              "& > :not(style)": { m: 1 },
              width: "70%",
            }}
            noValidate
            autoComplete="off"
          >
          <Typography
            variant="h6"
            gutterBottom
            component="div"
            style={{
              color: "#04116a",
              fontFamily: "NanumSquare-Regular",
              fontWeight: "bolder",
            }}
          >
              행위자*
            </Typography>
            <ReactTagInput
              tags={this.state.attacker}
              placeholder="행위자를 입력하고 Enter를 누르세요"
              maxTags={10}
              editable={true}
              readOnly={false}
              removeOnBackspace={true}
              onChange={(newTags) => this.setState({ attacker: newTags })}
              style={{
                backgroundColor: "white",
                border: "1.5px solid #afafaf",
              }}
            />
          </Box>

          <br></br>

          <Box
            component="form"
            sx={{
              "& > :not(style)": { m: 1 },
              width: "100%",
            }}
            noValidate
            autoComplete="off"
          >
            <Typography
              variant="h6"
              gutterBottom
              component="div"
              style={{
                color: "#04116a",
                fontFamily: "NanumSquare-Regular",
                fontWeight: "bolder",
              }}
            >
              상세설명
            </Typography>

            <textarea type="text" className="upload-com-input-desc-box" name="description" placeholder="구체적인 피해사실을 적어주세요" onChange={this.setDescription}/>

            {/* <TextField
              fullWidth
              multiline
              rows={8}
              // variant="outlined"
              onChange={this.setDescription}
              style={{
                backgroundColor: "white",
                border: "1px solid #afafaf",
                borderRadius: "8px",
              }}
            /> */}
          </Box>
          <br></br>
        </>
      );
    }
  }

  setKeyword = (e) => {
    console.log(e.target.value);
    this.setState({
      keyword: e.target.value,
    });
  };

  setAttacker = (e) => {
    this.setState({
      attacker: e.target.value,
    });
  };

  setDescription = (e) => {
    this.setState({
      description: e.target.value,
    });
  };

  submitButton = () => {
    const formData = new FormData();
    formData.append("file", this.state.file);
    formData.append("filename", this.state.fileName);
    formData.append("user", this.state.user);
    formData.append("case_num", this.props.location.state.casenum);
    const config = {
      headers: {
        enctype: "multipart/form-data",
      },
    };
    axios.post("/loadArtifactFile", formData, config).then((res) => {
      this.setState({ artifactList: res.data.data });
    });

    this.setState({ attacker: [] });
    this.setState({ description: "" });
    this.setState({ type: "" });

    if (this.state.attacker.length == 0) {
      return alert("행위자는 필수 입력 사항입니다!");
    }
    this.setState({ isSnackbarOpen: true });
    let body = {
      filetype: "컴퓨터 증거",
      isCheckedUpdate: this.state.artifactList,
      attacker: this.state.attacker,
      description: this.state.description,
      type: this.state.type,
      casenum: this.props.location.state.casenum,
      user: this.state.user,
      filename: this.state.fileName,
      work_startTime: this.state.work_startTime_input,
      work_endTime: this.state.work_endTime_input,
      holiday_date: this.state.holiday_date,
      parental_date: this.state.parental_date,
    };
    axios.post("/isCheckedUpdate", body).then(
      (res) =>
      this.ArtifactAnalysis(res.data.$oid,body)
    );
    // console.log(res);
    
  };

  ArtifactAnalysis=(_id,body)=>{
    let body2 = {
      isCheckedUpdate:body["isCheckedUpdate"],
      attacker: body["attacker"],
      type: body["type"],
      work_startTime: body["work_startTime"],
      work_endTime: body["work_endTime"],
      holiday_date: body["holiday_date"],
      parental_date: body["parental_date"],
      _id: _id
    };
    axios.post("/ArtifactAnalysis",body2)
  }

  searchClick = (e) => {
    this.setState({
      searchKeyword: e.target.value,
    });
    console.log(e.target.value);
  };

  render() {
    return (
      <div>
        <Header />
        <div className="wrap">
            <div className="jb_banner_uploadevidence">
              <div className="jb-case-flex-container">
                  <div className="jb-upload-flex-column-container">
                    <span className="jb_case_banner_title">
                      컴퓨터 사용 기록
                    </span>
                    <span className="jb_case_banner_subtitle">
                      JB Extractor에서 추출한 컴퓨터 사용 기록 파일을 업로드해주세요<br/>
                    </span>
                  </div>
                </div>
            </div>
        
        <div style={{ width: "80%", margin: "0 auto" }}>
          <div>
            <br></br>
            <form onSubmit={this.handleFormSubmit} className="jb-upload-evidence-flex-container">
                <input
                  type="file"
                  name="file"
                  id="input-file"
                  onChange={this.handleFileChange}
                />
                
                <button className="upload-com-file-button-container"
                  onClick={() => {
                    this.setState({
                      isListOpen: true,
                    });
                  }}
                >
                  등록
                </button>
            </form>
            <br></br>
          </div>
          <div
            // style={{
            //   backgroundColor: "white",
            //   borderRadius: "18px",
            //   boxShadow: "rgba(149, 157, 165, 0.2) 0px 8px 24px",
              // display: "flex",
              // flexDirection: "column",
              // textAlign: "center",
            // }}
          >
            {this.state.isListOpen ? <br></br> : null}
            {this.UserChooserOpen()}
            {this.state.isListOpen ? <br></br> : null}
          </div>
          <br></br>
          <div
            style={{
              height: "auto",
              maxHeight: "800px",
              overflowY: "auto",
              overflowX: "auto",
              boxShadow: "rgba(149, 157, 165, 0.2) 0px 8px 24px",
              borderRadius: "8px",
            }}
          >
            {this.listOpen()}
          </div>
          
          <br></br>
          <br></br>

          {this.state.isListOpen ? (
            <div className="upload-com-icon"/>
          ): null}
          
          <br></br>

          {this.state.isListOpen ? (
            <span className="jb-upload-com-text">
              선택한 항목을 아래에서 확인할 수 있습니다
            </span>
          ) : null}
          <br></br>
          <br></br>

          {this.state.isListOpen ? (
            <div
              style={{
                backgroundColor: "white",
                borderRadius: "8px",
                boxShadow: "rgba(149, 157, 165, 0.2) 0px 8px 24px",
                display: "flex",
                flexDirection: "column",
                textAlign: "center",
              }}
            >
              {this.checkedListOpen()}
            </div>
          ) : null}

          <br></br>
          <br></br>
          {/* <div
            style={{
              backgroundColor: "white",
              borderRadius: "8px",
              boxShadow: "rgba(149, 157, 165, 0.2) 0px 8px 24px",
            }}
          > */}
          {this.userInputOpen()}
          {/* </div> */}
          {this.state.isListOpen ? (
            <div>
              <br></br>
              {/* <Button
                onClick={() => {
                  this.submitButton();
                }}
                variant="contained"
              >
                <Typography variant="h6" display="block" gutterBottom>
                  확인
                </Typography>
              </Button> */}
              
            <div className="jb-upload-com-evidence-button-flex-container">
              <button className="upload-com-cancel-button-container" onClick={() => {
                  this.go();
                }}>
                취소
              </button>
              
              <button className="upload-com-button-container" onClick={() => {
                  this.submitButton();
                }}>
                확인
              </button>
            </div>

              <Snackbar
                open={this.state.isSnackbarOpen}
                autoHideDuration={6000}
                onClose={() => {
                  this.snackbarClose();
                }}
              >
                <Alert
                  onClose={() => {
                    this.snackbarClose();
                  }}
                  severity="success"
                  sx={{ width: "200%" }}
                >
                  완료되었습니다!
                </Alert>
              </Snackbar>

              

              {/* <Button
                variant="text"
                style={{ float: "right" }}
                onClick={() => {
                  this.go();
                }}
              >
                <Typography variant="h6" display="block" gutterBottom>
                  &lt; 되돌아가기
                </Typography>
              </Button> */}
              <br></br>
              <br></br>
            </div>
          ) : null}
        </div>
        </div>
        <Footer/>
      </div>
    );
  }
}

export default UploadEvidence_artifact;
